     6	fn write_stdout_or_exit(output: &str) {
     7	    let result = {
     8	        let stdout = io::stdout();
     9	        let mut stdout = stdout.lock();
    10	        stdout
    11	            .write_all(output.as_bytes())
    12	            .and_then(|()| stdout.write_all(b"\n"))
    13	    };
    14	    if let Err(error) = result {
    15	        if error.kind() == io::ErrorKind::BrokenPipe {
    16	            std::process::exit(0);
    17	        }
    18	        let _ = writeln!(
    19	            io::stderr().lock(),
    20	            "failed writing command output: {error}"
    21	        );
    22	        std::process::exit(1);
    23	    }
    24	}
    25	
    26	fn main() {
    27	    let wants_json = std::env::args_os().any(|argument| argument == "--json");
    28	    let cli = match Cli::try_parse() {
    29	        Ok(cli) => cli,
    30	        Err(error) if wants_json => {
    31	            write_stdout_or_exit(&app::error_json("cli", &error));
    32	            std::process::exit(2);
    33	        }
    34	        Err(error) => error.exit(),
    35	    };
    36	    let json = cli.json;
    37	    let command = cli.command_name();
    38	    // Apply and Undo start progress inside `app::run`, after human confirmation.
    39	    let progress = (!matches!(command, "apply" | "undo"))
    40	        .then(|| skillroster::present::ProgressGuard::start(command, json));
    41	    let (action_context, output) = match app::run_process(cli) {
    42	        Ok(process) => process,
    43	        Err(error) => {
    44	            if let Some(progress) = progress {
    45	                progress.finish();
    46	            }
    47	            if json {
    48	                write_stdout_or_exit(&app::error_json(command, error.as_ref()));
    49	            } else {
    50	                eprintln!("{}", skillroster::present::error_human(&error));
    51	            }
    52	            std::process::exit(1);
    53	        }
    54	    };
    55	
    56	    match output {
    57	        Ok(output) => {
    58	            if let Some(progress) = progress {
    59	                progress.finish();
    60	            }
    61	            write_stdout_or_exit(if json { &output.json } else { &output.human });
    62	        }
    63	        Err(error) => {
    64	            if let Some(progress) = progress {
    65	                progress.finish();
    66	            }
    67	            if json {
    68	                write_stdout_or_exit(&app::error_json_with_context(
    69	                    command,
    70	                    error.as_ref(),
    71	                    &action_context,
    72	                ));
    73	            } else if let Some(blocked) =
    74	                error.downcast_ref::<skillroster::roster_plan::RosterPlanBlocked>()
    75	            {
    76	                eprintln!(
    77	                    "{}",
    78	                    skillroster::present::blocked_roster_plan(&blocked.details)
    79	                );
    80	            } else {
    81	                eprintln!("{}", skillroster::present::error_human(&error));
    82	            }
    83	            std::process::exit(1);
    84	        }
    85	    }
    86	}
