 406	pub fn prepare(input: &str, ctx: &PrepareContext) -> Result<PreparedPlan> {
 407	    let input: PlanInput = serde_json::from_str(input)
 408	        .map_err(|error| ChangeError::new("invalid_plan_json", error.to_string()))?;
 409	    if input.schema_version != 1 {
 410	        return Err(ChangeError::new(
 411	            "unsupported_plan_schema",
 412	            format!(
 413	                "plan schema_version must be 1, got {}",
 414	                input.schema_version
 415	            ),
 416	        ));
 417	    }
 418	    if input.scan_id.trim().is_empty() {
 419	        return Err(ChangeError::new(
 420	            "invalid_plan",
 421	            "scan_id must not be empty",
 422	        ));
 423	    }
 424	    if input.operations.is_empty()
 425	        && input.roster_changes.is_empty()
 426	        && input.source_updates.is_empty()
 427	        && input.library_changes.is_empty()
 428	    {
 429	        return Err(ChangeError::new(
 430	            "invalid_plan",
 431	            "a plan must contain a filesystem operation or Roster change",
 432	        ));
 433	    }
 434	    match &ctx.operation_policy {
 435	        OperationPolicy::GovernanceOnly if !input.operations.is_empty() => {
 436	            return Err(ChangeError::new(
 437	                "operations_not_declarative",
 438	                "Agent-authored Plans may request Roster state changes only; filesystem operations are derived by trusted SkillRoster workflows",
 439	            ));
 440	        }
 441	        OperationPolicy::BootstrapSetup { .. }
 442	            if input.operations.iter().any(|operation| {
 443	                !matches!(
 444	                    operation,
 445	                    OperationInput::CreateDirectory { .. }
 446	                        | OperationInput::WriteFile { .. }
 447	                        | OperationInput::ReplaceFile { .. }
 448	                )
 449	            }) =>
 450	        {
 451	            return Err(ChangeError::new(
 452	                "invalid_setup_operation",
 453	                "bootstrap setup may only create directories and write or replace files in its fixed package",
 454	            ));
 455	        }
 456	        OperationPolicy::SourceUpdate
 457	            if input.operations.iter().any(|operation| {
 458	                !matches!(
 459	                    operation,
 460	                    OperationInput::ReplaceFile { .. } | OperationInput::WriteFile { .. }
 461	                )
 462	            }) =>
 463	        {
 464	            return Err(ChangeError::new(
 465	                "invalid_source_update_operation",
 640	                "plan_drifted",
 641	                format!(
 642	                    "{} expected {}, found {actual}",
 643	                    path.display(),
 644	                    projection.expected_before_fingerprint
 645	                ),
 646	            ));
 647	        }
 648	        path_projections.push(PathProjection {
 649	            path,
 650	            expected_before_fingerprint: projection.expected_before_fingerprint,
 651	            expected_after_fingerprint: projection.expected_after_fingerprint,
 652	        });
 653	    }
 654	
 655	    let digest_payload = plan_digest_payload(
 656	        &input.scan_id,
 657	        &input.evidence_ids,
 658	        &operations,
 659	        &input.roster_changes,
 660	        &input.source_updates,
 661	        &input.library_changes,
 662	        &path_projections,
 663	    )?;
 664	    let digest = format!("sha256:{}", hex::encode(Sha256::digest(digest_payload)));
 665	    Ok(PreparedPlan {
 666	        id: format!("plan_{}", ulid::Ulid::new()),
 667	        scan_id: input.scan_id,
 668	        evidence_ids: input.evidence_ids,
 669	        digest,
 670	        operations,
 671	        roster_changes: input.roster_changes,
 672	        source_updates: input.source_updates,
 673	        library_changes: input.library_changes,
 674	        path_projections,
 675	        approved_roots: roots,
 676	        state_dir,
 677	    })
 678	}
