701	fn apply_locked_with_anchored(
702	    plan: &PreparedPlan,
703	    anchored: AnchoredFs<'_>,
704	) -> Result<ApplyOutcome> {
705	    validate_prepared_plan(plan)?;
706	    run_before_sequence_validation_hook();
707	    validate_path_projections_anchored(&plan.path_projections, &anchored, false)?;
708	    validate_operation_sequence_anchored(&plan.operations, &anchored)?;
709	    reject_unresolved_recovery_except(&anchored, &plan.state_dir, "")?;
710	    anchored
711	        .require_atomic_noreplace_rename()
712	        .map_err(|error| ChangeError::io("validate mutation filesystem", &plan.state_dir, error))?;
713	
714	    let receipt_id = format!("receipt_{}", ulid::Ulid::new());
715	    let mut receipt = ChangeReceipt {
716	        id: receipt_id,
717	        plan_id: plan.id.clone(),
718	        status: ReceiptStatus::Applying,
719	        changed_paths: Vec::new(),
720	        compensations: Vec::new(),
721	        approved_roots: plan.approved_roots.clone(),
722	        state_dir: plan.state_dir.clone(),
723	        error: None,
724	        reverses_receipt_id: None,
725	        operation_results: Vec::new(),
726	    };
727	    persist_journal_with(&receipt, &anchored)?;
728	    run_before_mutation_hook();
729	
730	    for (index, operation) in plan.operations.iter().enumerate() {
731	        receipt.operation_results.push(JournalOperationResult {
732	            id: format!("operation_{}", ulid::Ulid::new()),
733	            position: index as u32,
734	            action: operation_kind(operation).to_owned(),
735	            target: operation.target().to_path_buf(),
736	            status: "applying".to_owned(),
737	            before_fingerprint: anchored.fingerprint(operation.target()).ok(),
738	            after_fingerprint: None,
739	            error: None,
740	        });
741	        persist_journal_with(&receipt, &anchored)?;
742	        if let Some(compensation) =
743	            stage_compensation(operation, &receipt.id, index, &plan.state_dir, &anchored)?
744	        {
745	            receipt.compensations.push(compensation);
746	            persist_journal_with(&receipt, &anchored)?;
747	        }
748	        run_before_execute_hook();
749	        match execute(operation, &receipt.id, index, &anchored) {
750	            Ok(compensation) => {
751	                receipt.changed_paths.push(operation.target().to_path_buf());
752	                if let Some(compensation) = compensation {
753	                    receipt.compensations.push(compensation);
754	                }
755	                if let Some(result) = receipt.operation_results.last_mut() {
756	                    result.status = "applied".to_owned();
757	                    result.after_fingerprint = anchored.fingerprint(operation.target()).ok();
758	                }
759	                if let Err(journal_error) = persist_journal_with(&receipt, &anchored) {
760	                    receipt.error = Some(journal_error.to_string());
761	                    let rollback = compensate_all(&receipt, &anchored);
762	                    receipt.status = if rollback.is_ok() {
763	                        ReceiptStatus::FailedRolledBack
764	                    } else {
765	                        ReceiptStatus::RecoveryRequired
766	                    };
767	                    finalize_rollback_results(&mut receipt, rollback.is_ok(), &anchored);
768	                    if let Err(rollback_error) = rollback {
769	                        receipt.error = Some(format!(
770	                            "{journal_error}; compensation failed: {rollback_error}"
771	                        ));
772	                    }
773	                    // Best effort: if storage remains unavailable, the last durable
774	                    // journal stays Applying and therefore blocks future writes.
775	                    let _ = persist_journal_with(&receipt, &anchored);
776	                    return Ok(ApplyOutcome {
777	                        receipt,
778	                        verification_passed: false,
779	                    });
780	                }
781	            }
782	            Err(error) => {
783	                if let Some(result) = receipt.operation_results.last_mut() {
784	                    result.status = "failed".to_owned();
785	                    result.after_fingerprint = anchored.fingerprint(operation.target()).ok();
786	                    result.error = Some(error.to_string());
787	                }
788	                receipt.error = Some(error.to_string());
789	                if error.code == "entry_identity_changed"
790	                    || operation_is_uncompensated_create(operation)
791	                {
792	                    let rollback = compensate_all(&receipt, &anchored);
793	                    receipt.status = ReceiptStatus::RecoveryRequired;
794	                    finalize_recovery_required_results(&mut receipt, rollback.is_ok(), &anchored);
795	                    if let Err(rollback_error) = rollback {
796	                        receipt.error = Some(format!(
797	                            "{error}; prior-operation compensation failed: {rollback_error}"
798	                        ));
799	                    }
800	                    let _ = persist_journal_with(&receipt, &anchored);
801	                    return Ok(ApplyOutcome {
802	                        receipt,
803	                        verification_passed: false,
804	                    });
805	                }
806	                // A durability barrier can fail after the directory entry changed.
807	                // Record the concrete recovery action before compensating so the
808	                // mutation is never reported as a clean rollback.
809	                match partial_operation_compensation(operation, &receipt.id, index, &anchored) {
810	                    Ok(Some(compensation)) => {
811	                        receipt.compensations.push(compensation);
812	                        receipt.changed_paths.push(operation.target().to_path_buf());
813	                        let _ = persist_journal_with(&receipt, &anchored);
814	                    }
815	                    Ok(None) => {}

 850	            }
 851	        }
 852	    }
 853	
 854	    if let Err(error) = validate_path_projections_anchored(&plan.path_projections, &anchored, true)
 855	    {
 856	        receipt.error = Some(error.to_string());
 857	        let rollback = compensate_all(&receipt, &anchored);
 858	        receipt.status = if rollback.is_ok() {
 859	            ReceiptStatus::FailedRolledBack
 860	        } else {
 861	            ReceiptStatus::RecoveryRequired
 862	        };
 863	        finalize_rollback_results(&mut receipt, rollback.is_ok(), &anchored);
 864	        if let Err(rollback_error) = rollback {
 865	            receipt.error = Some(format!("{error}; compensation failed: {rollback_error}"));
 866	        }
 867	        persist_journal_with(&receipt, &anchored)?;
 868	        return Ok(ApplyOutcome {
 869	            receipt,
 870	            verification_passed: false,
 871	        });
 872	    }
 873	
 874	    receipt.status = ReceiptStatus::Applied;
 875	    if let Err(error) = persist_journal_with(&receipt, &anchored) {
 876	        receipt.status = ReceiptStatus::RecoveryRequired;
 877	        receipt.error = Some(format!(
 878	            "changes were applied but the final receipt could not be persisted: {error}"
 879	        ));
 880	        let _ = persist_journal_with(&receipt, &anchored);
 881	        return Ok(ApplyOutcome {
 882	            receipt,
 883	            verification_passed: false,
 884	        });
 885	    }
 886	    Ok(ApplyOutcome {
 887	        receipt,
 888	        verification_passed: true,
 889	    })
 890	}
