 949	fn undo_locked_with_anchored(
 950	    receipt: &ChangeReceipt,
 951	    anchored: AnchoredFs<'_>,
 952	) -> Result<ApplyOutcome> {
 953	    if receipt.status != ReceiptStatus::Applied {
 954	        return Err(ChangeError::new(
 955	            "receipt_not_undoable",
 956	            "only an applied receipt can be undone",
 957	        ));
 958	    }
 959	    reject_unresolved_recovery_except(&anchored, &receipt.state_dir, &receipt.id)?;
 960	    anchored
 961	        .require_atomic_noreplace_rename()
 962	        .map_err(|error| {
 963	            ChangeError::io("validate mutation filesystem", &receipt.state_dir, error)
 964	        })?;
 965	    if reverse_receipt_exists(&anchored, &receipt.state_dir, &receipt.id)? {
 966	        return Err(ChangeError::new(
 967	            "receipt_already_undone",
 968	            format!("receipt {} has already been undone", receipt.id),
 969	        ));
 970	    }
 971	    let mut undo_receipt = ChangeReceipt {
 972	        id: format!("receipt_{}", ulid::Ulid::new()),
 973	        plan_id: receipt.plan_id.clone(),
 974	        status: ReceiptStatus::Applying,
 975	        changed_paths: Vec::new(),
 976	        compensations: Vec::new(),
 977	        approved_roots: receipt.approved_roots.clone(),
 978	        state_dir: receipt.state_dir.clone(),
 979	        error: None,
 980	        reverses_receipt_id: Some(receipt.id.clone()),
 981	        operation_results: receipt
 982	            .operation_results
 983	            .iter()
 984	            .map(|original| JournalOperationResult {
 985	                id: format!("operation_{}", ulid::Ulid::new()),
 986	                position: original.position,
 987	                action: format!("undo_{}", original.action),
 988	                target: original.target.clone(),
 989	                status: "applying".to_owned(),
 990	                before_fingerprint: anchored.fingerprint(&original.target).ok(),
 991	                after_fingerprint: None,
 992	                error: None,
 993	            })
 994	            .collect(),
 995	    };
 996	    persist_journal_with(&undo_receipt, &anchored)?;
 997	    match compensate_all(receipt, &anchored) {
 998	        Ok(()) => {
 999	            for result in &mut undo_receipt.operation_results {
1000	                result.status = "undone".to_owned();
1001	                result.after_fingerprint = anchored.fingerprint(&result.target).ok();
1002	            }
1003	            undo_receipt.status = ReceiptStatus::Undone;
1004	            undo_receipt.changed_paths = receipt.changed_paths.clone();
1005	            persist_journal_with(&undo_receipt, &anchored)?;
1006	            Ok(ApplyOutcome {
1007	                receipt: undo_receipt,
1008	                verification_passed: true,
1009	            })
1010	        }
1011	        Err(error) => {
1012	            for result in &mut undo_receipt.operation_results {
1013	                result.status = "failed".to_owned();
1014	                result.after_fingerprint = anchored.fingerprint(&result.target).ok();
1015	                result.error = Some(error.to_string());
1016	            }
1017	            undo_receipt.status = ReceiptStatus::RecoveryRequired;
1018	            undo_receipt.error = Some(error.to_string());
1019	            persist_journal_with(&undo_receipt, &anchored)?;
1020	            Ok(ApplyOutcome {
1021	                receipt: undo_receipt,
1022	                verification_passed: false,
1023	            })
1024	        }
1025	    }
