1028	/// Compensates an Apply that cannot be committed at the governance metadata
1029	/// layer. Unlike user-requested Undo this updates the original journal, so no
1030	/// untracked reverse Receipt is invented before SQLite finalization.
1783	fn execute(
1784	    operation: &Operation,
1785	    receipt_id: &str,
1786	    index: usize,
1787	    anchored: &AnchoredFs,
1788	) -> Result<Option<Compensation>> {
1789	    validate_anchored_current_state(operation, anchored)?;
1790	    match operation {
1791	        Operation::CreateDirectory { target, .. } => {
1792	            anchored
1793	                .create_dir(target)
1794	                .map_err(|e| anchored_mutation_error("create directory", target, e))?;
1795	            Ok(Some(Compensation::StashCreated {
1796	                path: target.clone(),
1797	                expected_fingerprint: anchored_fingerprint(anchored, target)?,
1798	            }))
1799	        }
1800	        Operation::CreateSymlink { target, source, .. } => {
1801	            anchored
1802	                .create_symlink(source, target)
1803	                .map_err(|e| anchored_mutation_error("create symlink", target, e))?;
1804	            Ok(Some(Compensation::StashCreated {
1805	                path: target.clone(),
1806	                expected_fingerprint: anchored_fingerprint(anchored, target)?,
1807	            }))
1808	        }
1809	        Operation::WriteFile {
1810	            target, content, ..
1811	        } => {
1812	            anchored
1813	                .create_file(target, content.as_bytes())
1814	                .map_err(|e| anchored_mutation_error("create file", target, e))?;
1815	            Ok(Some(Compensation::StashCreated {
1816	                path: target.clone(),
1817	                expected_fingerprint: anchored_fingerprint(anchored, target)?,
1818	            }))
1819	        }
1820	        Operation::ReplaceFile {
1821	            target, content, ..
1822	        } => {
1823	            replace_file(anchored, target, content, receipt_id, index)?;
1824	            Ok(None)
1825	        }
1826	        Operation::RemoveSymlink {
1827	            target,
1828	            expected_fingerprint,
1829	        } => {
1830	            let backup = move_backup_path(target, receipt_id, index)?;
